WITH enriched AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY browser ORDER BY started_at, id) row_seq, LAST_VALUE(country) IGNORE NULLS OVER (PARTITION BY browser, country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_country, ROW_NUMBER() OVER w_ordered event_seq FROM sessions WINDOW w_ordered AS (PARTITION BY customer_id, country ORDER BY started_at, id)) SELECT DATE_TRUNC('WEEK', started_at) AS week_start, DATE_TRUNC('QUARTER', started_at) AS quarter_start, CASE WHEN event_seq >= 7 THEN 'HIGH' ELSE 'LOW' END AS event_seq_tier, COUNT_IF(browser = 'Firefox') AS firefox_events, ROUND(AVG(event_seq), 2) AS avg_event_seq, ROUND(AVG(event_seq), 2) AS avg_event_seq_2 FROM enriched GROUP BY ROLLUP (DATE_TRUNC('WEEK', started_at), DATE_TRUNC('QUARTER', started_at), CASE WHEN event_seq >= 7 THEN 'HIGH' ELSE 'LOW' END) HAVING avg_event_seq < 0
